def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the full-length divider of color 2.
    divider = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            divider = ("h", r)
            break
    if divider is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                divider = ("v", c)
                break
    if divider is None:
        return out

    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != 2]
    if not cells:
        return out

    rs = [r for r, c, v in cells]
    cs = [c for r, c, v in cells]
    orient, pos = divider

    if orient == "h":
        if max(rs) < pos:  # object above divider
            dr = pos - 1 - max(rs)
        else:              # object below divider
            dr = pos + 1 - min(rs)
        for r, c, v in cells:
            out[r][c] = bg
        for r, c, v in cells:
            out[r + dr][c] = v
        stripe = min(r + dr for r, c, v in cells) - 1 if dr >= 0 else max(r + dr for r, c, v in cells) + 1
        if 0 <= stripe < h:
            out[stripe] = [8] * w
    else:
        if max(cs) < pos:  # object left of divider
            dc = pos - 1 - max(cs)
        else:              # object right of divider
            dc = pos + 1 - min(cs)
        for r, c, v in cells:
            out[r][c] = bg
        for r, c, v in cells:
            out[r][c + dc] = v
        stripe = min(c + dc for r, c, v in cells) - 1 if dc >= 0 else max(c + dc for r, c, v in cells) + 1
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8

    return out
